//! [ISO/IEC 9075-2:2023 §7.6] Data change delta tables, OLD TABLE, NEW
//! TABLE and FINAL TABLE of INSERT, UPDATE, DELETE and MERGE (RULES.md
//! D174).

use turborel::db::{Database, Direct, Session};
use turborel::error::{Code, SqlError};
use turborel::value::{Decimal, Value};

/// A session of `A` whose schema holds `T (K, V, G)`: K an identity, V
/// defaulted to 5, G generated as V * 10, a check that V is not negative;
/// rows (1, 1) and (2, 2).
fn session(db: &Database) -> Session {
    db.schema(
        "CREATE SCHEMA AUTHORIZATION A CREATE TABLE T (K INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, \
         V INTEGER DEFAULT 5 CHECK (V >= 0), G INTEGER GENERATED ALWAYS AS (V * 10))",
    )
    .unwrap();
    let s = db.session("A");
    s.run("INSERT INTO T (K, V) VALUES (1, 1), (2, 2)").unwrap();
    s.run("ALTER TABLE T ALTER COLUMN K RESTART WITH 10").unwrap();
    s.commit().unwrap();
    s
}

/// The rows `sql` gives in `s`, each its values joined by commas.
fn rows(s: &Session, sql: &str) -> Result<Vec<String>, SqlError> {
    let mut c = s.open_cursor(sql)?;
    let mut out = Vec::new();
    while let Some(r) = c.fetch()? {
        out.push(r.iter().map(ToString::to_string).collect::<Vec<_>>().join(","));
    }
    Ok(out)
}

/// Verifies: [ISO/IEC 9075-2:2023 §7.6 GR5b] NEW TABLE of an INSERT gives
/// each row as inserted, its identity, default and generated columns
/// given; FINAL TABLE alike; OLD TABLE of an UPDATE the rows before, NEW
/// TABLE after; OLD TABLE of a DELETE the rows deleted.
#[test]
fn delta_tables_of_each_statement_d174() {
    let db = Database::new();
    let s = session(&db);
    let inserted = rows(&s, "SELECT K, V, G FROM NEW TABLE (INSERT INTO T (V) VALUES (3), (DEFAULT)) ORDER BY K").unwrap();
    assert_eq!(inserted, vec!["10,3,30", "11,5,50"]);
    let fin = rows(&s, "SELECT K FROM FINAL TABLE (INSERT INTO T (V) VALUES (7)) AS F").unwrap();
    assert_eq!(fin, vec!["12"]);
    let old = rows(&s, "SELECT K, V FROM OLD TABLE (UPDATE T SET V = V + 100 WHERE K <= 2) ORDER BY K").unwrap();
    assert_eq!(old, vec!["1,1", "2,2"]);
    let new = rows(&s, "SELECT O.K, O.G FROM NEW TABLE (UPDATE T SET V = 0 WHERE K = 1) AS O (K, V, G)").unwrap();
    assert_eq!(new, vec!["1,0"]);
    let gone = rows(&s, "SELECT COUNT(*) FROM OLD TABLE (DELETE FROM T WHERE K >= 10)").unwrap();
    assert_eq!(gone, vec!["3"]);
    assert_eq!(rows(&s, "SELECT COUNT(*) FROM T").unwrap(), vec!["2"], "the statement's changes stand");
}

/// Verifies: [ISO/IEC 9075-2:2023 §7.6 GR5b iii] of a MERGE, NEW TABLE
/// gives the rows inserted and updated; OLD TABLE the rows updated and
/// deleted as they were.
#[test]
fn delta_tables_of_a_merge_d174() {
    let db = Database::new();
    let s = session(&db);
    let merge = "MERGE INTO T USING (VALUES (2, 20), (3, 30)) AS S (K, V) ON T.K = S.K \
                 WHEN MATCHED THEN UPDATE SET V = S.V WHEN NOT MATCHED THEN INSERT (K, V) VALUES (S.K, S.V)";
    assert_eq!(rows(&s, &format!("SELECT K, V FROM NEW TABLE ({merge}) ORDER BY K")).unwrap(), vec!["2,20", "3,30"]);
    let deleting = "MERGE INTO T USING (VALUES (1)) AS S (K) ON T.K = S.K WHEN MATCHED THEN DELETE";
    assert_eq!(rows(&s, &format!("SELECT K, V FROM OLD TABLE ({deleting})")).unwrap(), vec!["1,1"]);
}

/// Verifies: [ISO/IEC 9075-2:2023 §7.6 SR11a] OLD TABLE of an INSERT and
/// NEW or FINAL TABLE of a DELETE are refused, as is a MERGE that only
/// inserts read as OLD; a delta table elsewhere than the one table of a
/// cursor's query is refused; a statement refused undoes all of it.
#[test]
fn delta_tables_refused_d174() {
    let db = Database::new();
    let s = session(&db);
    let code = |sql: &str| rows(&s, sql).unwrap_err().code;
    assert_eq!(code("SELECT * FROM OLD TABLE (INSERT INTO T (V) VALUES (1))"), Code::SyntaxRule);
    assert_eq!(code("SELECT * FROM NEW TABLE (DELETE FROM T)"), Code::SyntaxRule);
    assert_eq!(code("SELECT * FROM FINAL TABLE (DELETE FROM T)"), Code::SyntaxRule);
    let inserting = "MERGE INTO T USING (VALUES (9)) AS S (K) ON T.K = S.K WHEN NOT MATCHED THEN INSERT (K) VALUES (S.K)";
    assert_eq!(code(&format!("SELECT * FROM OLD TABLE ({inserting})")), Code::SyntaxRule);
    assert_eq!(code("SELECT * FROM T, OLD TABLE (DELETE FROM T) AS D"), Code::SyntaxRule);
    assert_eq!(code("SELECT * FROM NEW TABLE (UPDATE T SET V = -1)"), Code::Constraint, "the check fails");
    assert_eq!(rows(&s, "SELECT V FROM T ORDER BY K").unwrap(), vec!["1", "2"], "nothing changed");
}

/// Verifies: [ISO/IEC 9075-2:2023 §7.6 GR5b, §15.21 GR6i] NEW TABLE
/// gives the rows a BEFORE trigger set, and none an AFTER trigger added;
/// under FINAL TABLE an AFTER trigger that changes the subject table is
/// refused with SQLSTATE 0W001, and the statement undone.
#[test]
fn delta_tables_and_triggers_d174() {
    let db = Database::new();
    let s = session(&db);
    s.run("CREATE TRIGGER B BEFORE INSERT ON T REFERENCING NEW AS N FOR EACH ROW SET N.V = N.V + 1").unwrap();
    s.run("CREATE TRIGGER F AFTER INSERT ON T REFERENCING NEW AS N FOR EACH ROW WHEN (N.V = 51) INSERT INTO T (V) VALUES (0)").unwrap();
    s.commit().unwrap();
    assert_eq!(rows(&s, "SELECT V FROM NEW TABLE (INSERT INTO T (V) VALUES (3))").unwrap(), vec!["4"]);
    assert_eq!(
        rows(&s, "SELECT V FROM NEW TABLE (INSERT INTO T (V) VALUES (50))").unwrap(),
        vec!["51"],
        "the AFTER trigger's row is not one"
    );
    let refused = rows(&s, "SELECT V FROM FINAL TABLE (INSERT INTO T (V) VALUES (50))").unwrap_err();
    // [§15.21 GR6m] raised as the triggered action exception of F.
    assert_eq!(refused.sqlstate().as_str(), "09000");
    assert!(refused.msg.contains("SQLSTATE 0W001"), "{}", refused.msg);
    assert_eq!(rows(&s, "SELECT COUNT(*) FROM T").unwrap(), vec!["5"], "the refused statement undone");
}

/// Verifies: [ISO/IEC 9075-2:2023 §7.6, §20.7] a query of a delta table
/// run directly is a query; prepared, its parameters take their types and
/// its statement runs once at each opening.
#[test]
fn delta_tables_run_directly_and_prepared_d174() {
    let db = Database::new();
    let s = session(&db);
    let Direct::Rows(mut c) = s.direct("SELECT K + 1 AS AFTER_K FROM OLD TABLE (DELETE FROM T WHERE K = 2)").unwrap() else {
        panic!("a query");
    };
    assert_eq!(c.columns[0].name.as_deref(), Some("AFTER_K"));
    assert_eq!(c.fetch().unwrap().unwrap()[0].to_string(), "3");
    let p = s.prepare("SELECT V, G FROM FINAL TABLE (INSERT INTO T (V) VALUES (?))").unwrap();
    for v in [7, 8] {
        let mut c = s.open_prepared(&p, &[Value::Exact(Decimal::new(v, 0))]).unwrap();
        assert_eq!(c.fetch().unwrap().unwrap()[1].to_string(), (v * 10).to_string());
    }
    assert_eq!(rows(&s, "SELECT COUNT(*) FROM T").unwrap(), vec!["3"]);
}

/// Verifies: [ISO/IEC 9075-2:2023 §7.6 GR5a, §15.18 GR15] under FINAL
/// TABLE a referential action of the statement that changes the subject
/// table is refused with SQLSTATE 27001; under NEW TABLE it runs.
#[test]
fn final_table_refuses_a_referential_action_on_its_table_d174() {
    let db = Database::new();
    db.schema("CREATE SCHEMA AUTHORIZATION A CREATE TABLE E (K INTEGER PRIMARY KEY, BOSS INTEGER REFERENCES E (K) ON UPDATE CASCADE)")
        .unwrap();
    let s = db.session("A");
    s.run("INSERT INTO E VALUES (1, NULL), (2, 1)").unwrap();
    let refused = rows(&s, "SELECT K FROM FINAL TABLE (UPDATE E SET K = 10 WHERE K = 1)").unwrap_err();
    assert_eq!(refused.sqlstate().as_str(), "27001");
    assert_eq!(rows(&s, "SELECT K FROM NEW TABLE (UPDATE E SET K = 10 WHERE K = 1)").unwrap(), vec!["10"]);
    assert_eq!(rows(&s, "SELECT BOSS FROM E WHERE K = 2").unwrap(), vec!["10"], "the cascade ran");
}

/// Verifies: [ISO/IEC 9075-2:2023 §7.6] a SELECT INTO of a procedure's
/// body reads a delta table, its statement run at each call.
#[test]
fn a_routine_reads_a_delta_table_d174() {
    let db = Database::new();
    let s = session(&db);
    s.run(
        "CREATE PROCEDURE ADDED (IN X INTEGER) MODIFIES SQL DATA BEGIN ATOMIC DECLARE NK INTEGER; \
         SELECT K INTO NK FROM NEW TABLE (INSERT INTO T (V) VALUES (X)); UPDATE T SET V = NK + 1000 WHERE K = NK; END",
    )
    .unwrap();
    s.run("CALL ADDED (1)").unwrap();
    s.run("CALL ADDED (2)").unwrap();
    assert_eq!(rows(&s, "SELECT K, V FROM T WHERE K >= 10 ORDER BY K").unwrap(), vec!["10,1010", "11,1011"]);
}
